/**
 * Neutral in Unicode, counted as ambiguous anyway: ░ sits in the picker's
 * preview's stat bar beside █, and ◉ and ✦ are hatch eyes beside × · °; each set keeps one
 * width, so a bar or a sprite row never changes width with its value or roll.
 */
const AMBIGUOUS_TOO: ReadonlySet<number> = new Set([0x2591, 0x25c9, 0x2726]);
const ZERO = /^[\p{Mn}\p{Me}\p{Cf}\p{Cc}]$/u;
const PRINTABLE_ASCII = /^[\x20-\x7e]*$/;
export const ELLIPSIS = '…';

function inRanges(t: readonly number[], cp: number): boolean {
  let lo = 0;
  let hi = t.length / 2 - 1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    if (cp < t[mid * 2]!) hi = mid - 1;
    else if (cp > t[mid * 2 + 1]!) lo = mid + 1;
    else return true;
  }
  return false;
}

/** One character's cells: 0, 1 or 2. */
export function charWidth(ch: string, o: WidthOptions = {}): number {
  const cp = ch.codePointAt(0) ?? 0;
  if (cp >= 0x20 && cp < 0x7f) return 1;
  if (ZERO.test(ch)) return 0;
  if (inRanges(WIDE, cp)) return 2;
  if (o.ambiguousCharacterWidth === 'wide' && (inRanges(AMBIGUOUS, cp) || AMBIGUOUS_TOO.has(cp))) return 2;
  return 1;
}

/** The cells `s` takes on the terminal. */
export function cellWidth(s: string, o: WidthOptions = {}): number {
  if (PRINTABLE_ASCII.test(s)) return s.length;
  let n = 0;
  for (const ch of s) n += charWidth(ch, o);
  return n;
}

/** `s` padded with spaces to `width` cells; never cut. */
export function padEndCells(s: string, width: number, o: WidthOptions = {}): string {
  return s + ' '.repeat(Math.max(0, width - cellWidth(s, o)));
}

/** The longest prefix of `s` that fits in `width` cells. */
export function sliceCells(s: string, width: number, o: WidthOptions = {}): string {
  let n = 0;
  let end = 0;
  for (const ch of s) {
    const w = charWidth(ch, o);
    if (n + w > width) break;
    n += w;
    end += ch.length;
  }
  return s.slice(0, end);
}

/**
 * `text` word-wrapped to `width` cells, a word longer than a line broken
 * inside it, each `\n` starting a new line. At most `maxLines`: past it, the
 * last kept line ends in `…`, so a cut never reads as the whole text.
 */
export function wrapCells(text: string, width: number, o: WidthOptions & { maxLines?: number } = {}): string[] {
  const w = Math.max(1, Math.floor(width));
  const lines: string[] = [];
  for (const para of text.split('\n')) {
    let line = '';
    let lw = 0;
    for (const word of para.split(/[ \t]+/)) {
      let rest = word;
      while (rest !== '') {
        const rw = cellWidth(rest, o);
        if (line === '' && rw <= w) {
          line = rest;
          lw = rw;
          rest = '';
        } else if (line === '') {
          const head = sliceCells(rest, w, o) || String.fromCodePoint(rest.codePointAt(0)!);
          lines.push(head);
          rest = rest.slice(head.length);
        } else if (lw + 1 + rw <= w) {
          line += ` ${rest}`;
          lw += 1 + rw;
          rest = '';
        } else {
          lines.push(line);
          line = '';
          lw = 0;
        }
      }
    }
    lines.push(line);
  }
  const max = Math.max(1, Math.floor(o.maxLines ?? Infinity));
  if (lines.length <= max) return lines;
  const kept = lines.slice(0, max);
  kept[max - 1] = sliceCells(kept[max - 1]!, w - cellWidth(ELLIPSIS, o), o).trimEnd() + ELLIPSIS;
  return kept;
}

