      "description": "After every answered turn, one short call on model reads the last chatTurnsToRead turns of your chat and writes commentAfterEachTurn, one line in the character's voice for its speech bubble. The same call also writes suggestNextPrompt when that is on. secondsBetweenComments spaces commentAfterEachTurn out. Off: the buddy stays quiet after turns.",
      "default": true
    },
    "model": {
      "type": "string",
      "title": "Model the buddy uses (opus, sonnet, haiku, a model id, or inherit)",
      "description": "The model behind every buddy call: commentAfterEachTurn, suggestNextPrompt and the answer to every /buddy question. Give an alias (opus, sonnet, haiku) or a full model id. inherit uses whatever model your chat is on, read at each call, and opus when it cannot be read.",
      "default": "opus"
    },
    "effort": {
      "type": "string",
      "title": "How hard the buddy's model thinks: low, medium, high, xhigh, max or inherit",
      "description": "The thinking effort of every buddy call, on the model option's model. Higher is slower and costs more. inherit uses the effort of your chat's latest request; before its first request, or when that request sets none or a number, no effort is sent and the model's own default applies.",
      "default": "low"
    },
    "secondsBetweenComments": {
      "type": "number",
      "title": "Fewest seconds between two commentAfterEachTurn (0 = after every answer)",
      "description": "With commentAfterEachTurn on, a new commentAfterEachTurn waits at least this many seconds after the previous one. 0 says one after every answered turn. It does not space out suggestNextPrompt, which is written every turn.",
      "default": 0
    },
    "suggestNextPrompt": {
      "type": "boolean",
      "title": "The buddy suggests your next prompt (uses tokens)",
      "description": "After every answered turn, the same short call on model proposes your next prompt, as you would type it, as the grey suggestion in the prompt box. Claude Code's own suggestion is held back and shown only when the buddy has none. Off: Claude Code's own suggestion shows as usual.",
      "default": true
    },
    "promptToMainChat": {
      "type": "boolean",
      "title": "Prompt the main chat",
      "description": "The buddy may send Claude a prompt of its own after a turn, at most one per prompt of yours; Claude reads it as the buddy's, never yours.",
      "default": true
    },
    "promptWhenIdle": {
      "type": "boolean",
      "title": "Prompt an idle chat",
      "description": "After the chat sits idle 30 minutes, the buddy asks a model whether Claude left owed work and, if so, sends Claude one line to resume it; never a git push, a deletion, a publication or an account step.",
      "default": false
    },
    "chatTurnsToRead": {
      "type": "number",
      "title": "How many recent chat turns the buddy remembers (1 to 10)",
      "description": "The buddy's memory: your chat's latest turns (your prompt and Claude's answer), each with what the buddy showed after it (its commentAfterEachTurn and suggestNextPrompt) and your /buddy questions with its answers. Every buddy call reads it; the buddy knows it remembers only this far and says so when asked about anything older. Kept per session and per character. More turns, more tokens per call.",
      "default": 4
    },
    "logLevel": {
      "type": "string",
      "title": "How much the plugin logs: error, info or debug",
      "description": "What the plugin writes to logFile. error: failures only. info: also sessions, commands, questions and their outcomes, commentAfterEachTurn and menu picks. debug: also question text, the shape of model results and drawing decisions. It never logs who you are.",
      "default": "info"
    },
    "logFile": {
      "type": "string",
      "title": "Where the plugin log goes (empty = no log file)",
      "description": "The default follows CLAUDE_CONFIG_DIR: $CLAUDE_CONFIG_DIR/buddy/buddy.log when it is set, ~/.claude/buddy/buddy.log when it is not. A path you give is used as written, with ~ as your home folder and a leading $CLAUDE_CONFIG_DIR as the config folder. One JSON line per record; past 1 MB it is archived whole to the next free .1, .2, …, none ever overwritten or deleted; /buddy log shows its path and last 20 lines. Empty: no log file; failures still go to Claude Code's debug log.",
      "default": "$CLAUDE_CONFIG_DIR/buddy/buddy.log"
    },
    "saveRounds": {
      "type": "boolean",
      "title": "Keep a file per turn of what went into buddy and came out",
      "description": "For seeing what the buddy sees and says: one text file per main-chat turn, in the chat's own folder beside its transcript ({config}/projects/{project}/{session id}/buddy/, next to memory.json, the buddy's memory of that chat). Every turn is kept (round-001.txt on, each new round numbered after the highest, none ever overwritten; ls -t lists them newest first), each holding, in the order it happened, from the turn's start to the next turn's start: the prompt the turn began with, each tool call buddy heard with its arguments and output (each value cut at 500 characters), every buddy log record at any level, each bubble line and prompt-box suggestion, the turn's end as buddy filed it into its memory, and every model call buddy made, its system prompt, prompt and reply verbatim. They hold what the transcript beside them holds: your prompts, Claude's answers and tool output. Off: no round files.",
      "default": true
    },
    "ambiguousCharacterWidth": {
      "type": "string",
      "title": "Width of ambiguous-width characters in your terminal: narrow or wide",
      "description": "Some characters (East Asian ambiguous width) take one column in most terminals and two in some, often with a CJK locale. narrow: 1 column; wide: 2. The speech bubble and the character are laid out to match. Change it only if the bubble's border looks misaligned.",
      "default": "narrow"
    }
  }
}

